17	const (
18		defaultMergeRadarDepth = 2
19		maxMergeRadarDepth     = 3
20	)
21	
22	type mergeRadarFlags struct {
23		Repo     string
24		Base     string
25		JSON     bool
26		NoIntent bool
27		Depth    int
28		Refs     []string
29	}
30	
31	func parseMergeRadarFlags(args []string) (mergeRadarFlags, error) {
32		flags := mergeRadarFlags{Depth: defaultMergeRadarDepth}
33		for index := 0; index < len(args); index++ {
34			arg := args[index]
35			value := func() (string, error) {
36				index++
37				if index >= len(args) {
38					return "", fmt.Errorf("%s requires a value", arg)
39				}
40				return args[index], nil
41			}
42			switch arg {
43			case "--repo":
44				item, err := value()
45				if err != nil {
46					return flags, err
47				}
48				flags.Repo = item
49			case "--base":
50				item, err := value()
51				if err != nil {
52					return flags, err
53				}
54				flags.Base = item
55			case "--depth":
56				item, err := value()
57				if err != nil {
58					return flags, err
59				}
60				depth, convErr := strconv.Atoi(item)
61				if convErr != nil || depth < 1 || depth > maxMergeRadarDepth {
62					return flags, fmt.Errorf("--depth must be an integer from 1 to %d, got %q", maxMergeRadarDepth, item)
63				}
64				flags.Depth = depth
65			case "--json":
66				flags.JSON = true
67			case "--no-intent":
68				flags.NoIntent = true
69			default:
70				if strings.HasPrefix(arg, "-") {
71					return flags, fmt.Errorf("unknown flag %s for merge-radar", arg)
72				}
73				flags.Refs = append(flags.Refs, arg)
74			}
75		}
76		if len(flags.Refs) != 2 {
77			return flags, errors.New("merge-radar needs exactly two branches: entire graph merge-radar <branch-a> <branch-b> [--base <ref>]")
78		}
79		if flags.Refs[0] == flags.Refs[1] {
80			return flags, fmt.Errorf("merge-radar needs two different branches, got %q twice", flags.Refs[0])
81		}
82		return flags, nil
83	}
