123	func shortSHA(sha string) string {
124		if len(sha) > 7 {
125			return sha[:7]
126		}
127		return sha
128	}
129	
130	func writeMergeRadarText(out io.Writer, report sem.MergeReport, depth int) {
131		fmt.Fprintf(out, "MergeRadar  base %s  depth %d\n", shortSHA(report.Base), depth)
132		fmt.Fprintf(out, "  A  %-24s %s  %d files, %d entities changed\n", report.A.Ref, shortSHA(report.A.Commit), report.A.Files, report.A.Entities)
133		fmt.Fprintf(out, "  B  %-24s %s  %d files, %d entities changed\n\n", report.B.Ref, shortSHA(report.B.Commit), report.B.Files, report.B.Entities)
134	
135		if len(report.Conflicts) == 0 {
136			fmt.Fprintln(out, "No cross-branch conflicts found at this depth.")
137			fmt.Fprintln(out, "The graph saw no entity changed on one branch that changed or added code on the other references.")
138			fmt.Fprintln(out, "This is not proof the merge is safe: relationships through configuration, serialised data or runtime strings are invisible to the graph.")
139		} else {
140			fmt.Fprintf(out, "%d potential conflict(s). Labelled potential until a merged tree is actually tested.\n\n", len(report.Conflicts))
141			for i, c := range report.Conflicts {
142				writeMergeConflict(out, i+1, c)
143			}
144		}
145	
146		fmt.Fprintln(out, "Verify before trusting this report:")
147		fmt.Fprintf(out, "  git merge-tree --write-tree %s %s    # scratch merge, no checkout\n", report.A.Ref, report.B.Ref)
148		fmt.Fprintln(out, "  then run the tests that touch the files listed above against that tree.")
149	
150		if len(report.Warnings) > 0 {
151			fmt.Fprintf(out, "\n%d analysis warning(s):\n", len(report.Warnings))
152			for _, w := range report.Warnings {
153				file := ""
154				if w.FilePath != "" {
155					file = " " + w.FilePath
156				}
157				fmt.Fprintf(out, "  %s%s: %s\n", w.Code, file, w.EffectOnCompleteness)
158			}
159		}
160	}
