162	func writeMergeConflict(out io.Writer, n int, c sem.MergeConflict) {
163		fmt.Fprintf(out, "[%d] %s  %s\n", n, strings.ToUpper(c.Kind), c.Confidence)
164		fmt.Fprintf(out, "    changed on %-12s %s %s  %s:%d  %s\n", c.ChangedOn, c.Changed.Kind, c.Changed.Name, c.Changed.Path, c.Changed.Line, c.Changed.Type)
165		if c.Changed.OldSignature != "" && c.Changed.NewSignature != "" && c.Changed.OldSignature != c.Changed.NewSignature {
166			fmt.Fprintf(out, "      - %s\n      + %s\n", c.Changed.OldSignature, c.Changed.NewSignature)
167		}
168		if c.Consumer != nil {
169			via := ""
170			if len(c.Via) > 0 {
171				names := make([]string, 0, len(c.Via))
172				for _, v := range c.Via {
173					names = append(names, v.Name)
174				}
175				via = "  via " + strings.Join(names, " -> ")
176			}
177			label := "consumer on"
178			if c.Kind == sem.ConflictDirect {
179				label = "also changed on"
180			}
181			fmt.Fprintf(out, "    %-11s %-12s %s %s  %s:%d  %s%s\n", label, c.ConsumerOn, c.Consumer.Kind, c.Consumer.Name, c.Consumer.Path, c.Consumer.Line, c.Consumer.Type, via)
182		}
183		writeIntentLine(out, "why "+c.ChangedOn, c.ChangedIntent)
184		if c.Consumer != nil {
185			writeIntentLine(out, "why "+c.ConsumerOn, c.ConsumerIntent)
186		}
187		fmt.Fprintf(out, "    => %s\n\n", c.Explanation)
188	}
