190	func writeIntentLine(out io.Writer, label string, intent *sem.CheckpointIntent) {
191		if intent == nil {
192			fmt.Fprintf(out, "    %-24s (no commits on this side carry checkpoints)\n", label)
193			return
194		}
195		if intent.Source == sem.IntentSourceMissing {
196			note := intent.Note
197			if note == "" {
198				note = "no recorded intent"
199			}
200			fmt.Fprintf(out, "    %-24s [no intent: %s]  commit %s\n", label, note, shortSHA(intent.Commit))
201			return
202		}
203		fmt.Fprintf(out, "    %-24s \"%s\"\n", label, intent.Intent)
204		evidence := []string{"checkpoint " + intent.CheckpointID, "commit " + shortSHA(intent.Commit), "from " + intent.Source}
205		if intent.Agent != "" {
206			evidence = append(evidence, intent.Agent)
207		}
208		if intent.Match != "" {
209			evidence = append(evidence, "matched by "+intent.Match)
210		}
211		fmt.Fprintf(out, "    %-24s %s\n", "", strings.Join(evidence, " · "))
212		if intent.Note != "" {
213			fmt.Fprintf(out, "    %-24s note: %s\n", "", intent.Note)
214		}
215	}
